// eglGetProcAddress itself: libEGL.so's eglGetProcAddress calls it.
void (*gles_eglGetProcAddress(const char *name))(void) {
  if (name == NULL) return NULL;
  for (size_t i = 0; i < sizeof procs / sizeof procs[0]; i++)
    if (strcmp(procs[i].name, name) == 0) return procs[i].function;
  return NULL;
}

// GLES_STATS in the environment counts each frame (gles(2), ENVIRONMENT), set as the library loads; GLES_STATS=gpu also
// times each step on the GPU.
extern void gles_setStats(int on);
__attribute__((constructor)) static void stats_from_environment(void) {
  const char *s = getenv("GLES_STATS");
  if (s) gles_setStats(strcmp(s, "gpu") == 0 ? 2 : 1);
}
